#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package ZeroFormatter@1.7.0 #:package Microsoft.IO.RecyclableMemoryStream@2.3.2 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Buffers; using System.Threading.Channels; using ZeroFormatter; using Microsoft.IO;  var builder = WebApplication.CreateBuilder(args);  // 1. 内存池配置（线程安全） builder.Services.AddSingleton<RecyclableMemoryStreamManager>(_ =>      new RecyclableMemoryStreamManager(         blockSize: 1.MB,         largeBufferMultiple: 4.MB,         maximumBufferSize: 16.MB));  // 2. 零拷贝消息通道（Disruptor模式） var messageChannel = Channel.CreateBounded<MessageEnvelope>(     new BoundedChannelOptions(1_000_000) {         SingleReader = true,         AllowSynchronousContinuations = true,         FullMode = BoundedChannelFullMode.DropOldest     });  builder.Services.AddSingleton(messageChannel); builder.Services.AddHostedService<ZeroCopyProcessor>();  // 3. 线程本地内存分配器 builder.Services.AddSingleton<IMemoryAllocator>(_ =>      new ThreadLocalAllocator(         blockSize: 1.MB,         maxBlocksPerThread: 1000,         cacheLineSize: 64));  var app = builder.Build(); app.MapGet("/", () => "ZeroFormatter Integration Ready"); app.Run();  // 零拷贝消息结构 [ZeroFormattable, SkipLocalsInit] public struct MessageEnvelope {     [Index(0)] public long Timestamp;     [Index(1)] public int MessageType;     [Index(2)] public byte[] Payload;          [MethodImpl(MethodImplOptions.AggressiveInlining)]     public void Clear() => Payload = null; }  // 高性能处理器 public sealed class ZeroCopyProcessor : BackgroundService {     private readonly Channel<MessageEnvelope> _channel;     private readonly ThreadLocal<Span<byte>> _buffer;     private readonly RecyclableMemoryStreamManager _memoryManager;      public ZeroCopyProcessor(         Channel<MessageEnvelope> channel,         RecyclableMemoryStreamManager memoryManager)     {         _channel = channel;         _memoryManager = memoryManager;         _buffer = new(() => stackalloc byte[1024], trackAllValues: false);     }      [MethodImpl(MethodImplOptions.AggressiveOptimization)]     protected override async Task ExecuteAsync(CancellationToken stoppingToken)     {         await foreach (var message in _channel.Reader.ReadAllAsync(stoppingToken))         {             var buffer = _buffer.Value;             ProcessMessage(message, buffer);         }     }      [SkipLocalsInit]     private unsafe void ProcessMessage(MessageEnvelope message, Span<byte> buffer)     {         fixed (byte* ptr = buffer)         {             // 零拷贝序列化/反序列化             var serialized = ZeroFormatterSerializer.Serialize(message);             using var stream = _memoryManager.GetStream();             stream.Write(serialized);         }     } }  // 线程本地内存分配器 public class ThreadLocalAllocator : IMemoryAllocator {     private readonly ThreadLocal<Memory<byte>> _threadLocalMemory;      public ThreadLocalAllocator(int blockSize, int maxBlocksPerThread, int cacheLineSize)     {         _threadLocalMemory = new(() => {             var memory = new Memory<byte>(new byte[blockSize]);             // 确保内存对齐             if ((long)Unsafe.AsPointer(ref memory.Span[0]) % cacheLineSize != 0)                 throw new InvalidOperationException("Memory not aligned");             return memory;         }, trackAllValues: false);     }      public Memory<byte> Rent(int size) => _threadLocalMemory.Value.Slice(0, size);     public void Return(Memory<byte> memory) { } }
